        return 0
    if n == 1 and m == 1:
        return 1
    eulerian = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    for i in range(1, n):
        eulerian[i][1] = 1
        for j in range(2, i + 1):
            eulerian[i][j] = eulerian[i - 1][j - 1] + (i - 1) * eulerian[i - 1][j]
