def lps(s):
    """
    Finds the length of the longest palindromic subsequence in the given string.
    """
    n = len(s)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    for l in range(1, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            if i == j:
                dp[i][j] = 1
            elif s[i] == s[j]:
                dp[i][j] = 2
                if l > 2:
                    dp[i][j] += dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]
