def max_product(nums: List[int]) -> int:
    def lis_product(nums: List[int]) -> int:
        n = len(nums)
        dp = [0] * n
        max_product = 0

        for i in range(n):
            dp[i] = nums[i]
            for j in range(i):
                if nums[j] < nums[i]:
                    dp[i] = max(dp[i], dp[j] * nums[i])
            max_product = max(max_product, dp[i])

